from branch import freeze
from run import lab
base=lab.read(lab.OUT/'h1-lantern-harbour/config.json')
style=' An exquisitely detailed surrealist oil painting, dream logic, luminous jewel-colored enamel against deep velvet shadows. Monumental readable silhouettes, delicate engraved textures, sharp reflected highlights and dimensional shading. Broad cinematic composition, dramatic near and far forms, rich colors separated by dark negative space.'
stages=[(8,'shelter-forms-around-the-boat','A huge pearly shell arch shelters a small red paper boat with a golden lantern in a calm turquoise pool. The threatening wave has become the curved roof of a warm harbour, lined with amber windows. A smaller spiral shell house stands to the right, linked to the arch by a delicate golden bridge. The red boat sits clearly in the foreground beneath the protective arch; its lantern casts a bright reflection across the water. Outside the arch the sky remains deep midnight blue.'),(10,'the-traveller-becomes-a-beacon','Inside a sheltered pearl-shell harbour, a red paper boat unfolds upward into a small red lighthouse. The pointed folded bow becomes a tall triangular red tower, while its golden lantern rises toward the top. Red folded paper ridges remain visible along the tower and little hull-shaped base at the waterline. A vast pearly arch and warm amber windows protect the new light. Calm turquoise water reflects the red tower; an open channel runs from it toward the dark sea on the right.'),(13,'a-home-that-guides-others','A vermilion red lighthouse made from folded paper rises from a small boat-shaped island in a luminous pearl-shell harbour. One brilliant golden lantern shines at its top. The red tower has crisp folded ridges, warm amber windows and a small red boat-like base. A huge ivory shell arch curves overhead, its inner surface lined with golden windows. A thin golden beam reaches across calm turquoise water toward two tiny red paper boats arriving through an opening at the right. Beyond them lies the dark blue sea.'),(16,'the-light-is-shared','A warm sheltered harbour beneath enormous pearly shell arches. A red folded-paper lighthouse stands to the left of center, its golden lamp shining over a winding turquoise channel. Several small red paper boats, each carrying a tiny golden lantern, gather near its foot and along the channel toward the open sea. Golden window lights repeat across the shell houses. The nearest curved shell roof frames the upper edge while the water and boats have space below. The distant storm is small beyond the harbour entrance at the right.')]
phrases=[p for p in base['phrases'] if p['start']<=7.5]
phrases.extend([dict(start=7.5,duration=8,zoom=.1,turn=-12,travel=[.28,-.05],center=[.55,.55],radius=3.5),dict(start=12,duration=10,zoom=-.16,turn=17,travel=[-.09,.08],center=[.7,.5],radius=3),dict(kind='wave',start=12,duration=11,amplitude=.032,wavelength=1.5,cycles=.6)])
noise=[(8,.64),(8.5,.6),(9,.55),(9.5,.58),(10,.64),(10.5,.7),(11,.75),(11.5,.77),(12,.72),(12.5,.64),(13,.66),(13.5,.72),(14,.76),(14.5,.70),(15,.6),(15.5,.5),(16,.60),(16.5,.69),(17,.67),(17.5,.5)]
freeze('h1-lantern-harbour','h2-a-light-for-others',180,18,[dict(at=t,name=n,prompt=p+style) for t,n,p in stages],[dict(at=t,noise=n) for t,n in noise],phrases)
